<?php
namespace Joomla\Component\Blog\Administrator\Controller;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use Joomla\Database\DatabaseInterface;
final class CommentsController extends BaseController { public function state():void{$this->change(false);}public function delete():void{$this->change(true);}private function change(bool $delete):void{Session::checkToken()or jexit('Invalid token');$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.edit.state','com_blog'))throw new \RuntimeException('Not authorised',403);$ids=array_map('intval',(array)$app->getInput()->post->get('cid',[],'array'));if($ids){$db=Factory::getContainer()->get(DatabaseInterface::class);$q=$db->createQuery();if($delete)$q->delete('#__blog_comments')->whereIn('id',$ids);else$q->update('#__blog_comments')->set('state='.(int)$app->getInput()->getInt('value'))->whereIn('id',$ids);$db->setQuery($q)->execute();}$app->redirect(Route::_('index.php?option=com_blog&view=comments',false));} }
